import type { RicosPalette } from './../../ricos-types/index.js';
import {
  getThemeColorTokenOpacity,
  isThemeColorToken,
  setThemeColorTokenOpacity,
  stripThemeColorTokenOpacity,
  themeColorTokenToHex,
} from './../../_shared/theme-color-token.js';

export const isHexColor = (str: string) =>
  /^#(?:[0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(str);

export const combineHexWithOpacity = (hexColor: string | undefined, opacityPercentage: number) => {
  if (!hexColor) {
    return;
  }
  if (isThemeColorToken(hexColor)) {
    return setThemeColorTokenOpacity(hexColor, opacityPercentage);
  }

  if (opacityPercentage === 100) {
    return hexColor.slice(0, 7);
  }

  const alpha = Math.round((opacityPercentage / 100) * 255);
  const alphaHex = alpha.toString(16).padStart(2, '0').toUpperCase();

  return `${hexColor.slice(0, 7)}${alphaHex}`;
};

export const getOpacityFromHex = (hexColorWithAlpha: string | undefined): number => {
  if (isThemeColorToken(hexColorWithAlpha)) {
    return getThemeColorTokenOpacity(hexColorWithAlpha);
  }
  if (!hexColorWithAlpha || hexColorWithAlpha.length === 7 || !isHexColor(hexColorWithAlpha)) {
    return 100;
  }

  const hex = hexColorWithAlpha.replace('#', '');

  const alphaHex = hex.slice(6, 8);
  const alphaDecimal = parseInt(alphaHex, 16);
  return Math.round((alphaDecimal / 255) * 100);
};

export const getHexColorFromAlpha = (hexColorWithAlpha: string | undefined) => {
  if (isThemeColorToken(hexColorWithAlpha)) {
    return stripThemeColorTokenOpacity(hexColorWithAlpha);
  }
  if (!hexColorWithAlpha || hexColorWithAlpha.length === 7 || !isHexColor(hexColorWithAlpha)) {
    return hexColorWithAlpha;
  }

  return hexColorWithAlpha.slice(0, 7);
};

const resolveContrastHexColor = (color: string, palette?: RicosPalette): string | undefined => {
  if (!isThemeColorToken(color)) {
    return color;
  }

  const resolvedColor = palette ? themeColorTokenToHex(color, palette) : undefined;
  return resolvedColor && isHexColor(resolvedColor) ? resolvedColor : undefined;
};

// Based on https://gist.github.com/Yemolai/86233b88ac904e06a7a29938dc3b0295
// Added handle for alpha channel: when opacity is below 50% we don't take
// color contrast into consideration
export const getContrastYIQ = (color: string, palette?: RicosPalette) => {
  const contrastHex = resolveContrastHexColor(color, palette);
  if (!contrastHex) {
    return 'black';
  }

  let hex = contrastHex;
  // If a leading # is provided, remove it
  if (hex.slice(0, 1) === '#') {
    hex = hex.slice(1);
  }

  // If a three-character hex code, make six-character
  if (hex.length === 3 || hex.length === 4) {
    hex = hex
      .split('')
      .map(hex => {
        return hex + hex;
      })
      .join('');
  }

  // Convert to RGB value
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);
  const alphaHex = hex.substring(6, 8) || 'FF';
  const a = parseInt(alphaHex, 16);

  // Get YIQ ratio
  const yiq = (r * 299 + g * 587 + b * 114) / 1000;

  // Check contrast
  return yiq >= 128 || a < 127 ? 'black' : 'white';
};
